'use strict';
const menuButton=document.querySelector('.menu-toggle');
const menu=document.querySelector('#mobile-nav');
function closeMenu(){menu.hidden=true;menuButton.setAttribute('aria-expanded','false');menuButton.setAttribute('aria-label','Открыть меню')}
menuButton.addEventListener('click',()=>{const expanded=menuButton.getAttribute('aria-expanded')==='true';menu.hidden=expanded;menuButton.setAttribute('aria-expanded',String(!expanded));menuButton.setAttribute('aria-label',expanded?'Открыть меню':'Закрыть меню')});
menu.querySelectorAll('a').forEach(link=>link.addEventListener('click',closeMenu));
document.addEventListener('keydown',event=>{if(event.key==='Escape'&&!menu.hidden){closeMenu();menuButton.focus()}});
document.addEventListener('click',event=>{if(!menu.hidden&&!event.target.closest('.site-header'))closeMenu()});
const calm=matchMedia('(prefers-reduced-motion: reduce)');
function transition(update){if(calm.matches||!document.startViewTransition){update();return}document.startViewTransition(update)}
function indicator(group,selector){group.classList.add('tabs-js');const mark=document.createElement('span');mark.className='tab-indicator';mark.setAttribute('aria-hidden','true');group.prepend(mark);const place=()=>{const active=group.querySelector(selector);if(!active)return;mark.style.width=active.offsetWidth+'px';mark.style.height=active.offsetHeight+'px';mark.style.transform=`translate(${active.offsetLeft}px,${active.offsetTop}px)`};place();requestAnimationFrame(()=>mark.classList.add('ready'));new ResizeObserver(place).observe(group);return place}
const placeSpace=indicator(document.querySelector('.space-tabs'),'[aria-selected=true]');
const placeDuration=indicator(document.querySelector('.duration-tabs'),'[aria-pressed=true]');
function tick(element){element.classList.remove('tick');void element.offsetWidth;element.classList.add('tick')}
const spaces={gym:{title:'Больше места.\nБольше возможностей.',description:'Силовые тренажёры Matrix и свободные веса. Пространство для тех, кто только начинает, и тех, кто давно в движении.',detail:'Тренируйся в своём темпе',alt:'Тренажёрный зал Sport Town с оборудованием Matrix'},cardio:{title:'Движение, которое\nзаряжает.',description:'Беговые дорожки и кардиооборудование. Начни с лёгкой разминки или посвяти тренировку выносливости.',detail:'Поймай свой ритм',alt:'Кардиозона Sport Town с беговыми дорожками у окон'},functional:{title:'Сила за пределами\nтренажёров.',description:'Выделенная зона для работы с собственным весом и функциональным оборудованием. Добавь разнообразия в привычные занятия.',detail:'Больше свободы движения',alt:'Функциональная зона Sport Town с подвесным оборудованием'}};
const spaceButtons=[...document.querySelectorAll('[data-space]')];
function setSpace(key){const space=spaces[key],image=document.querySelector('.space-image');if(image.dataset.gallery===key)return;spaceButtons.forEach(button=>{const selected=button.dataset.space===key;button.setAttribute('aria-selected',String(selected));button.tabIndex=selected?0:-1});placeSpace();image.dataset.gallery=key;image.setAttribute('aria-label',`Увеличить фото: ${space.alt}`);document.querySelector('#space-panel').setAttribute('aria-labelledby',`tab-${key}`);const photo=document.querySelector('#space-photo');const next=new Image();next.src=`assets/${key}.webp`;next.decode().catch(()=>{}).then(()=>transition(()=>{photo.src=next.src;photo.alt=space.alt;document.querySelector('#space-title').textContent=space.title;document.querySelector('#space-description').textContent=space.description;document.querySelector('#space-detail').textContent=space.detail}))}
spaceButtons.forEach((button,index)=>{button.addEventListener('click',()=>setSpace(button.dataset.space));button.addEventListener('keydown',event=>{let next;if(event.key==='ArrowRight')next=(index+1)%spaceButtons.length;if(event.key==='ArrowLeft')next=(index+spaceButtons.length-1)%spaceButtons.length;if(event.key==='Home')next=0;if(event.key==='End')next=spaceButtons.length-1;if(next!==undefined){event.preventDefault();setSpace(spaceButtons[next].dataset.space);spaceButtons[next].focus()}})});
const cards={1:{price:6700,period:'Месяц для себя',label:'1 МЕСЯЦ',action:'Узнать о карте на 1 месяц'},3:{price:17900,period:'Время войти в ритм',label:'3 МЕСЯЦА',action:'Узнать о карте на 3 месяца'},6:{price:26500,period:'Полгода в движении',label:'6 МЕСЯЦЕВ',action:'Узнать о карте на 6 месяцев'},12:{price:39000,period:'Год в твоём ритме',label:'12 МЕСЯЦЕВ',action:'Узнать о карте на 12 месяцев'}};
const number=value=>new Intl.NumberFormat('ru-RU').format(value);
document.querySelectorAll('[data-months]').forEach(button=>button.addEventListener('click',()=>{const months=Number(button.dataset.months),card=cards[months];document.querySelectorAll('[data-months]').forEach(item=>item.setAttribute('aria-pressed',String(item===button)));placeDuration();document.querySelector('#card-period').textContent=card.period;document.querySelector('#card-price').textContent=number(card.price);document.querySelector('#monthly-price').textContent=(card.price%months?'≈ ':'')+number(Math.round(card.price/months));document.querySelector('#total-price').textContent=number(card.price);document.querySelector('#card-validity').textContent=card.label;document.querySelector('#card-action').firstChild.textContent=card.action+' ';if(!calm.matches){tick(document.querySelector('#card-price'));tick(document.querySelector('#monthly-price'))}}));
const trainingDetails=[...document.querySelectorAll('.training')];
trainingDetails.forEach(detail=>detail.addEventListener('toggle',()=>{if(!detail.open)return;trainingDetails.forEach(other=>{if(other!==detail)other.open=false});const photo=document.querySelector('#training-photo'),src=`assets/${detail.dataset.training}.webp`;if(photo.getAttribute('src')===src)return;const next=new Image();next.src=src;next.decode().catch(()=>{}).then(()=>transition(()=>{photo.src=src;photo.alt=detail.querySelector('summary span').textContent+' в Sport Town'}))}));
document.querySelectorAll('.training a[href="#club"]').forEach(link=>link.addEventListener('click',()=>setSpace(link.closest('[data-training]').dataset.training)));
const gallery=document.querySelector('#gallery');
const galleryItems=[{key:'gym',name:'Тренажёрный зал'},{key:'cardio',name:'Кардиозона'},{key:'functional',name:'Функциональная зона'},{key:'detail',name:'Характер Sport Town'}];
let galleryIndex=0;
function renderGallery(){const item=galleryItems[galleryIndex];document.querySelector('#gallery-image').src=`assets/${item.key}.webp`;document.querySelector('#gallery-image').alt=item.name+' — Sport Town';document.querySelector('#gallery-caption').textContent=item.name;document.querySelector('#gallery-count').textContent=`${galleryIndex+1} / ${galleryItems.length}`}
function moveGallery(delta){galleryIndex=(galleryIndex+delta+galleryItems.length)%galleryItems.length;renderGallery()}
document.querySelectorAll('[data-gallery]').forEach(button=>button.addEventListener('click',()=>{galleryIndex=Math.max(0,galleryItems.findIndex(item=>item.key===button.dataset.gallery));renderGallery();gallery.showModal()}));
document.querySelector('#gallery-close').addEventListener('click',()=>gallery.close());document.querySelector('#gallery-next').addEventListener('click',()=>moveGallery(1));document.querySelector('#gallery-prev').addEventListener('click',()=>moveGallery(-1));gallery.addEventListener('click',event=>{if(event.target===gallery){const rect=gallery.getBoundingClientRect();if(event.clientX<rect.left||event.clientX>rect.right||event.clientY<rect.top||event.clientY>rect.bottom)gallery.close()}});gallery.addEventListener('keydown',event=>{if(event.key==='ArrowRight'){event.preventDefault();moveGallery(1)}if(event.key==='ArrowLeft'){event.preventDefault();moveGallery(-1)}});
const memberCard=document.querySelector('.member-card');
if(matchMedia('(hover: hover) and (pointer: fine)').matches){memberCard.addEventListener('pointermove',event=>{if(calm.matches)return;const rect=memberCard.getBoundingClientRect(),x=(event.clientX-rect.left)/rect.width,y=(event.clientY-rect.top)/rect.height;memberCard.classList.add('is-tilting');memberCard.style.setProperty('--ry',`${(x-.5)*10}deg`);memberCard.style.setProperty('--rx',`${(.5-y)*8}deg`);memberCard.style.setProperty('--mx',`${x*100}%`);memberCard.style.setProperty('--my',`${y*100}%`)});memberCard.addEventListener('pointerleave',()=>{memberCard.classList.remove('is-tilting');['--rx','--ry','--mx','--my'].forEach(name=>memberCard.style.removeProperty(name))})}
